// @ts-check
const { test, expect } = require('@playwright/test');

const SERVER_BASE_URL = (process.env.RDF4J_SERVER_BASE_URL
	|| 'http://127.0.0.1:8091/rdf4j-server').replace(/\/+$/, '');
const WORKBENCH_BASE_URL = (process.env.RDF4J_WORKBENCH_BASE_URL
	|| 'http://127.0.0.1:8091/rdf4j-workbench').replace(/\/+$/, '');
const REPOSITORY_ID = `query-stream-compat-${process.pid}-${Date.now()}`;
const REPOSITORY_URL = `${SERVER_BASE_URL}/repositories/${REPOSITORY_ID}`;
const QUERY_URL = `${WORKBENCH_BASE_URL}/repositories/${REPOSITORY_ID}/query`;
const NDJSON_ACCEPT = 'application/vnd.rdf4j.workbench+ndjson';

test.beforeAll(async ({ request }) => {
	const existing = await request.get(REPOSITORY_URL);
	expect([400, 404], 'the generated repository id must not already exist').toContain(existing.status());
	const created = await request.put(REPOSITORY_URL, {
		headers: { 'Content-Type': 'text/turtle' },
		data: repositoryConfiguration(REPOSITORY_ID)
	});
	expect([200, 201, 204]).toContain(created.status());
	const statements = [
		'<urn:compat:alice> <urn:compat:name> "Alice" .',
		'<urn:compat:bob> <urn:compat:name> "Bob" .',
		'<urn:compat:alice> <urn:compat:type> <urn:compat:Person> <urn:compat:people> .'
	].join('\n');
	const loaded = await request.post(`${REPOSITORY_URL}/statements`, {
		headers: { 'Content-Type': 'application/n-quads' },
		data: statements
	});
	expect([200, 201, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
	await request.delete(REPOSITORY_URL).catch(() => {});
});

