test('executes a typed SELECT once and keeps result controls interactive', async ({ page }, testInfo) => {
	const monitor = monitorPage(page);
	await openQueryPage(page, monitor);
	const colonNodes = await page.locator('#query-page').evaluate(root => {
		const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
		const matches = [];
		let node;
		while ((node = walker.nextNode())) {
			if (node.nodeValue.trim() === ':') {
				matches.push({ parent: node.parentElement && node.parentElement.outerHTML.slice(0, 180) });
			}
		}
		return matches;
	});
	await testInfo.attach('standalone-colon-text-nodes.json', {
		body: Buffer.from(JSON.stringify(colonNodes, null, 2)),
		contentType: 'application/json'
	});
	console.log(`[query-stream-dom-audit] standalone-colon-text-nodes=${JSON.stringify(colonNodes)}`);

	// Keep this exact real-browser reproduction first: HTMLSelectElement.children is
	// an HTMLCollection, unlike the array-like test doubles used by the unit suite.
	await executeAndWait(page, monitor,
		'SELECT ?item ?label WHERE { VALUES (?item ?label) { (<urn:review:one> "first"@en) (<urn:review:two> "second") } }');
	const result = page.locator('#query-results .query-result-layout');
	await expect(result).toBeVisible();
	try {
		await expect(result.locator('table.data tbody tr')).toHaveCount(2, { timeout: 15000 });
	} catch (error) {
		const state = await page.locator('#query-results').evaluate(root => ({
			busy: root.getAttribute('aria-busy'),
			text: root.innerText,
			layout: root.querySelector('.query-result-layout')
				? root.querySelector('.query-result-layout').outerHTML.slice(0, 5000) : ''
		}));
		await testInfo.attach('select-result-failure-state.json', {
			body: Buffer.from(JSON.stringify({ state, errors: monitor.errors, queryPosts: monitor.queryPosts,
				queryResponses: monitor.queryResponses }, null, 2)),
			contentType: 'application/json'
		});
		throw new Error(`${error.message}; result state=${JSON.stringify(state)}; query responses=${JSON.stringify(monitor.queryResponses)}`);
	}
	await expect(result.locator('table.data tbody')).toContainText('first');
	await expect(result.locator('table.data tbody')).toContainText('second');
	assertOneStreamingPost(monitor);

	const optionsToggle = result.locator('.query-result-toolbar__disclosures button').filter({ hasText: 'Options' });
	await optionsToggle.click();
	await expect(optionsToggle).toHaveAttribute('aria-expanded', 'true');
	const layout = result.locator('select[name="result-layout"]');
	await layout.selectOption('records');
	await expect(result).toHaveAttribute('data-effective-layout', 'records');
	await expect(result.locator('.query-result-record[data-query-record-index="0"] h3'))
		.toHaveText('Record 1');
	await layout.selectOption('table');
	await expect(result).toHaveAttribute('data-effective-layout', 'table');

	const downloadToggle = result.locator('.query-result-toolbar__disclosures button').filter({ hasText: 'Download' });
	await downloadToggle.click();
	await expect(downloadToggle).toHaveAttribute('aria-expanded', 'true');
	const downloadButton = result.locator('.query-result-download-button');
	await expect(downloadButton).toBeVisible();
	const downloadRequest = page.waitForRequest(request => isNativeDownloadRequest(request), { timeout: 10000 });
	await downloadButton.click();
	const rawDownload = await downloadRequest;
	const downloadParams = new URLSearchParams(rawDownload.postData() || '');
	expect(downloadParams.get('Accept')).toBeTruthy();
	expect(rawDownload.headers().accept || '').not.toContain(NDJSON_ACCEPT);
	expect(pageErrorsSince(monitor, 0)).toEqual([]);
});

test('streams unlimited results before completion with a bounded table window', async ({ page }, testInfo) => {
	test.setTimeout(90000);
	const monitor = monitorPage(page);
	await openQueryPage(page, monitor);
	await page.locator('#query-options-toggle').click();
	await page.locator('#limit_query').selectOption('0');

	const rowCount = 20000;
	const values = Array.from({ length: rowCount }, (_, index) => String(index)).join(' ');
	await setEditor(page, 0, `SELECT ?item WHERE { VALUES ?item { ${values} } }`);
	await page.evaluate(() => {
		const root = document.getElementById('query-results');
		const metrics = { startedAt: performance.now(), firstContentAt: null, terminalAt: null, busyRowsObserved: false };
		window.__queryStreamScaleMetrics = metrics;
		const observe = () => {
			const busy = root.getAttribute('aria-busy') === 'true';
			const dataRows = root.querySelectorAll('tbody tr:not([data-query-spacer])').length;
			if (busy && dataRows > 0 && metrics.firstContentAt === null) {
				metrics.firstContentAt = performance.now();
				metrics.busyRowsObserved = true;
			}
			if (!busy && metrics.firstContentAt !== null && metrics.terminalAt === null) {
				metrics.terminalAt = performance.now();
			}
		};
		new MutationObserver(observe).observe(root, {
			attributes: true, attributeFilter: ['aria-busy'], childList: true, subtree: true
		});
	});

	const previousExecutions = monitor.executions.length;
	const startedAt = Date.now();
	await page.locator('#exec').click();
	await expect.poll(() => monitor.executions.length - previousExecutions).toBe(1);
	await page.waitForFunction(() => window.__queryStreamScaleMetrics.busyRowsObserved, null, { timeout: 30000 });
	const rowsWhileStreaming = await page.locator('#query-results tbody tr:not([data-query-spacer])').count();
	await page.waitForFunction(() => window.__queryStreamScaleMetrics.terminalAt !== null, null, { timeout: 60000 });
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false');
	const result = page.locator('#query-results .query-result-layout');
	await expect(result.locator('.query-result-status')).toHaveText(`${rowCount} results.`);
	await assertOneStreamingPost(monitor);

	const options = result.locator('.query-result-toolbar__disclosures button').filter({ hasText: 'Options' });
	await options.click();
	const layout = result.locator('select[name="result-layout"]');
	await layout.selectOption('table');
	await expect(result).toHaveAttribute('data-effective-layout', 'table');
	const tableWrap = result.locator('.query-result-table-wrap');
	const rowsAtStart = await tableWrap.locator('tbody tr[data-query-row-index]').evaluateAll(rows =>
		rows.map(row => Number(row.getAttribute('data-query-row-index'))));
	expect(rowsAtStart).toContain(0);

	await tableWrap.evaluate(element => {
		element.scrollTop = element.scrollHeight / 2;
		element.dispatchEvent(new Event('scroll'));
	});
	await expect.poll(async () => {
		const indexes = await tableWrap.locator('tbody tr[data-query-row-index]').evaluateAll(rows =>
			rows.map(row => Number(row.getAttribute('data-query-row-index'))));
		return indexes.some(index => index > rowCount / 3 && index < rowCount * 2 / 3);
	}).toBe(true);

	await tableWrap.evaluate(element => {
		element.scrollTop = element.scrollHeight;
		element.dispatchEvent(new Event('scroll'));
	});
	await expect.poll(async () => {
		const indexes = await tableWrap.locator('tbody tr[data-query-row-index]').evaluateAll(rows =>
			rows.map(row => Number(row.getAttribute('data-query-row-index'))));
		return Math.max(...indexes);
	}).toBeGreaterThanOrEqual(rowCount - 200);
	const finalMetrics = await page.evaluate(() => ({
		stream: window.__queryStreamScaleMetrics,
		status: document.querySelector('#query-results .query-result-status').textContent,
		rowCount: document.querySelectorAll('#query-results tbody tr[data-query-row-index]').length,
		tableRowsIncludingSpacers: document.querySelectorAll('#query-results tbody tr').length,
		resultDomNodes: document.querySelectorAll('#query-results *').length
	}));
	expect(finalMetrics.rowCount).toBeLessThanOrEqual(80);
	expect(finalMetrics.tableRowsIncludingSpacers).toBeLessThanOrEqual(82);
	expect(finalMetrics.resultDomNodes).toBeLessThan(500);
	expect(finalMetrics.stream.firstContentAt).toBeLessThan(finalMetrics.stream.terminalAt);
	expect(finalMetrics.stream.busyRowsObserved).toBe(true);
	expect(pageErrorsSince(monitor, 0)).toEqual([]);
	const observation = {
		logicalRowCount: rowCount, rowsWhileStreaming, durationMs: Date.now() - startedAt,
		timeToFirstRowsMs: finalMetrics.stream.firstContentAt - finalMetrics.stream.startedAt,
		streamingAfterFirstRowsMs: finalMetrics.stream.terminalAt - finalMetrics.stream.firstContentAt,
		visibleDataRows: finalMetrics.rowCount,
		tableRowsIncludingSpacers: finalMetrics.tableRowsIncludingSpacers,
		resultDomNodes: finalMetrics.resultDomNodes,
		status: finalMetrics.status,
		busyRowsObserved: finalMetrics.stream.busyRowsObserved
	};
	console.log(`[unlimited-stream-scale] ${JSON.stringify(observation)}`);
	await testInfo.attach('unlimited-stream-scale-metrics.json', {
		body: Buffer.from(JSON.stringify(observation, null, 2)),
		contentType: 'application/json'
	});
});

