test('result toolbar controls stay intrinsic and options anchor to their trigger while paging', async ({ page }) => {
	const monitor = monitorPage(page);
	await openQueryPage(page, monitor);
	await page.locator('#query-options-toggle').click();
	await page.locator('#limit_query').selectOption('10');
	const pageValues = Array.from({ length: 11 }, (_, index) =>
		`<urn:toolbar:item${String(index + 1).padStart(2, '0')}>`).join(' ');
	await executeAndWait(page, monitor,
		`SELECT ?item WHERE { VALUES ?item { ${pageValues} } } ORDER BY ?item`);

	const result = page.locator('#query-results .query-result-layout');
	const countLabel = result.locator('.query-result-navigation__label').first();
	await expect(countLabel).toHaveText('Page 1 of 2');
	const toolbar = result.locator('.query-result-toolbar');
	const downloadToggle = toolbar.locator('button').filter({ hasText: 'Download' });
	const optionsToggle = toolbar.locator('button').filter({ hasText: 'Options' });
	for (const toggle of [downloadToggle, optionsToggle]) {
		const width = await toggle.evaluate(button => button.getBoundingClientRect().width);
		expect.soft(width, 'toolbar disclosures should use their intrinsic button width').toBeLessThan(180);
	}

	await optionsToggle.click();
	const optionsGeometry = await optionsToggle.evaluate(button => {
		const panel = document.getElementById(button.getAttribute('aria-controls'));
		const triggerRect = button.getBoundingClientRect();
		const panelRect = panel.getBoundingClientRect();
		return {
			triggerCenter: triggerRect.left + triggerRect.width / 2,
			triggerTop: triggerRect.top,
			triggerBottom: triggerRect.bottom,
			panelTop: panelRect.top,
			panelBottom: panelRect.bottom,
			panelLeft: panelRect.left,
			anchor: parseFloat(panel.style.getPropertyValue('--workbench-disclosure-anchor-x')),
			viewportHeight: window.innerHeight
		};
	});
	expect(optionsGeometry.panelTop).toBeGreaterThanOrEqual(optionsGeometry.triggerBottom);
	expect(Number.isFinite(optionsGeometry.anchor), 'the panel arrow should have a measured anchor').toBe(true);
	expect(optionsGeometry.panelLeft + optionsGeometry.anchor).toBeCloseTo(optionsGeometry.triggerCenter, 0);
	expect(optionsGeometry.triggerTop).toBeGreaterThanOrEqual(0);
	expect(optionsGeometry.panelBottom, 'the complete Options panel should remain in the viewport')
		.toBeLessThanOrEqual(optionsGeometry.viewportHeight);

	await optionsToggle.click();
	await page.setViewportSize({ width: 390, height: 844 });
	await optionsToggle.focus();
	await page.keyboard.press('Enter');
	await expect(optionsToggle).toHaveAttribute('aria-expanded', 'true');
	await page.evaluate(() => new Promise(resolve => requestAnimationFrame(resolve)));
	const mobileGeometry = await optionsToggle.evaluate(button => {
		const panel = document.getElementById(button.getAttribute('aria-controls'));
		const triggerRect = button.getBoundingClientRect();
		const panelRect = panel.getBoundingClientRect();
		return {
			triggerCenter: triggerRect.left + triggerRect.width / 2,
			triggerTop: triggerRect.top,
			triggerBottom: triggerRect.bottom,
			panelTop: panelRect.top,
			panelBottom: panelRect.bottom,
			panelLeft: panelRect.left,
			panelRight: panelRect.right,
			anchor: parseFloat(panel.style.getPropertyValue('--workbench-disclosure-anchor-x')),
			viewportWidth: document.documentElement.clientWidth,
			viewportHeight: window.innerHeight,
			devicePixelTolerance: 1 / window.devicePixelRatio
		};
	});
	expect(mobileGeometry.panelTop).toBeGreaterThanOrEqual(mobileGeometry.triggerBottom);
	expect(mobileGeometry.triggerTop).toBeGreaterThanOrEqual(0);
	expect(mobileGeometry.panelBottom, 'the complete mobile Options panel should remain in the viewport')
		.toBeLessThanOrEqual(mobileGeometry.viewportHeight + mobileGeometry.devicePixelTolerance);
	expect(mobileGeometry.panelLeft).toBeGreaterThanOrEqual(0);
	expect(mobileGeometry.panelRight).toBeLessThanOrEqual(mobileGeometry.viewportWidth);
	expect(mobileGeometry.panelLeft + mobileGeometry.anchor).toBeCloseTo(mobileGeometry.triggerCenter, 0);

	const nextPage = result.getByRole('button', { name: 'Next page' });
	await nextPage.click();
	await expect.poll(() => monitor.executions.length).toBe(2);
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false');
	await expect(countLabel).toHaveText('Page 2 of 2');
	expect(pageErrorsSince(monitor, 0)).toEqual([]);
});

test('loads the complete Explain, Compare, and Diff query route dependencies', async ({ page }) => {
	const monitor = monitorPage(page);
	// Isolate script/dependency behavior from the separate Accept-variant cache contract.
	const queryPageModel = [
		{ type: 'head', version: 1 },
		{ type: 'view', id: 'query' },
		{ type: 'metadata', values: { workbench: {} } },
		{ type: 'end' }
	].map(record => JSON.stringify(record) + '\n').join('');
	await page.route('**/rdf4j-workbench/repositories/*/query', async route => {
		const request = route.request();
		if (request.isNavigationRequest() || request.method() !== 'GET'
				|| !(request.headers().accept || '').includes(NDJSON_ACCEPT)) {
			await route.continue();
			return;
		}
		await route.fulfill({
			status: 200,
			headers: { 'Content-Type': `${NDJSON_ACCEPT};charset=UTF-8`, 'Cache-Control': 'no-store' },
			body: queryPageModel
		});
	});
	await openQueryPage(page, monitor);
	const dependencyAudit = await page.evaluate(() => {
		const requiredScripts = [
			'queryCancelPolicy.js', 'diff.min.js', 'viz/viz.js', 'viz/full.render.js',
			'svg-pan-zoom.min.js', 'queryExplanationHighlighter.js'
		];
		const loaded = requiredScripts.filter(name => Array.from(document.scripts).some(script =>
			script.src.endsWith('/scripts/' + name) && script.getAttribute('data-workbench-loaded') === 'true'));
		return {
			requiredScripts,
			loaded,
			queryCancelPolicy: !!(window.workbench && window.workbench.queryCancelPolicy
				&& window.workbench.queryCancelPolicy.getExplainControlIds),
			queryExplanationHighlighter: !!(window.workbench && window.workbench.queryExplanationHighlighter),
			diff: typeof Diff !== 'undefined' && typeof Diff.diffLines === 'function',
			viz: typeof Viz !== 'undefined',
			svgPanZoom: typeof svgPanZoom === 'function'
		};
	});
	expect(dependencyAudit.loaded, 'the Lit query route must load the complete legacy script graph')
		.toEqual(dependencyAudit.requiredScripts);
	expect(dependencyAudit.queryCancelPolicy).toBe(true);
	expect(dependencyAudit.queryExplanationHighlighter).toBe(true);
	expect(dependencyAudit.diff).toBe(true);
	expect(dependencyAudit.viz).toBe(true);
	expect(dependencyAudit.svgPanZoom).toBe(true);
	await setEditor(page, 0, 'SELECT * WHERE { ?s ?p ?o } LIMIT 10');
	await page.locator('#explain-trigger').click();
	await waitForStableExplanation(page, '#query-explanation', monitor);
	await expect(page.locator('#compare-toggle')).toBeVisible();

	await page.locator('#compare-toggle').click();
	await expect(page.locator('#query-compare-pane')).toBeVisible();
	await setEditor(page, 1, 'ASK { ?s ?p ?o }');
	await page.locator('#explain-compare-trigger').click();
	await waitForStableExplanation(page, '#query-explanation', monitor);
	await waitForStableExplanation(page, '#query-explanation-compare', monitor);
	const diff = page.locator('#query-diff-trigger');
	await expect(diff).toBeEnabled();
	await diff.click();
	await expect(page.locator('#query-diff-modal')).toHaveClass(/query-diff-modal--open/);
	await expect(page.locator('#query-diff-query .query-diff-row').first()).toBeVisible();
	await expect(page.locator('#query-diff-explanation .query-diff-row').first()).toBeVisible();
	await page.keyboard.press('Escape');
	await expect(page.locator('#query-diff-modal')).not.toHaveClass(/query-diff-modal--open/);
	expect(pageErrorsSince(monitor, 0)).toEqual([]);
});

function repositoryConfiguration(repositoryId) {
	return `@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>.
@prefix config: <tag:rdf4j.org,2023:config/>.
[] a config:Repository ;
   config:rep.id "${repositoryId}" ;
   rdfs:label "Disposable query stream compatibility fixture" ;
   config:rep.impl [ config:rep.type "openrdf:SailRepository" ;
      config:sail.impl [ config:sail.type "openrdf:MemoryStore" ; config:mem.persist false ] ].`;
}

function monitorPage(page) {
	const monitor = { errors: [], executions: [], pageModels: [], queryPosts: [], queryResponses: [] };
	page.on('pageerror', error => monitor.errors.push(error.message));
	page.on('response', response => {
		const request = response.request();
		const accept = request.headers().accept || '';
		if (request.method() === 'POST' && /\/query(?:[?#]|$)/.test(request.url())
				&& accept.includes(NDJSON_ACCEPT)) {
			monitor.queryResponses.push({
				url: request.url(), status: response.status(),
				contentType: response.headers()['content-type'] || ''
			});
		}
		if (request.method() !== 'GET' || !accept.includes(NDJSON_ACCEPT)) {
			return;
		}
		const entry = {
			url: request.url(),
			status: response.status(),
			contentType: response.headers()['content-type'] || '',
			vary: response.headers().vary || '',
			accept,
			body: '',
			bodyPromise: Promise.resolve()
		};
		entry.bodyPromise = response.text().then(body => { entry.body = body; }).catch(error => {
			entry.body = `Unable to read response: ${error.message}`;
		});
		monitor.pageModels.push(entry);
	});
	page.on('request', request => {
		if (request.method() !== 'POST' || !/\/query(?:[?#]|$)/.test(request.url())) {
			return;
		}
		const entry = {
			url: request.url(),
			accept: request.headers().accept || '',
			contentType: request.headers()['content-type'] || '',
			body: request.postData() || ''
		};
		monitor.queryPosts.push(entry);
		// Streaming executions use FormData, so parsing the body as URL-encoded
		// parameters misses the request entirely. The negotiated media type is
		// the stable discriminator for the one query execution POST.
		if (entry.accept.includes(NDJSON_ACCEPT)) {
			monitor.executions.push(entry);
		}
	});
	return monitor;
}

async function openQueryPage(page, monitor) {
	await page.setViewportSize({ width: 1440, height: 1000 });
	const navigation = await page.goto(QUERY_URL, { waitUntil: 'domcontentloaded' });
	await page.waitForFunction(() => {
		const mount = document.getElementById('workbench-app');
		const alert = mount && mount.querySelector('[role="alert"]');
		return document.getElementById('query-form') || alert && alert.textContent.trim();
	}, null, { timeout: 15000 }).catch(() => {});
	if (!(await page.locator('#query-form').count())) {
		const visibleAlerts = await page.locator('#workbench-app [role="alert"]')
			.allTextContents().catch(() => []);
		await Promise.all(monitor.pageModels.map(response => response.bodyPromise));
		const dataResponses = monitor.pageModels.map(response => ({
			url: response.url,
			status: response.status,
			contentType: response.contentType,
			accept: response.accept,
			firstBytes: response.body.slice(0, 180)
		}));
		const documentState = await page.evaluate(() => ({
			url: location.href,
			title: document.title,
			bodyText: document.body ? document.body.innerText.slice(0, 400) : '',
			appAttributes: document.getElementById('workbench-app')
				? document.getElementById('workbench-app').outerHTML.slice(0, 300) : ''
		}));
		throw new Error('Query page failed before mounting its form. Visible errors: '
			+ visibleAlerts.map(text => text.trim()).filter(Boolean).join(' | ')
			+ '; browser errors: ' + monitor.errors.join(' | ')
			+ '; page model responses: ' + JSON.stringify(dataResponses)
			+ '; navigation status=' + (navigation && navigation.status())
			+ '; page=' + JSON.stringify(documentState));
	}
	await page.locator('#query-form').waitFor({ state: 'visible' });
	await page.locator('.CodeMirror').first().waitFor({ state: 'visible' });
}

async function executeAndWait(page, monitor, query) {
	const previousExecutionCount = monitor.executions.length;
	const previousPageErrorCount = monitor.errors.length;
	await setEditor(page, 0, query);
	const requestOrError = new Promise(resolve => {
		const onRequest = request => {
			if (request.method() === 'POST' && /\/query(?:[?#]|$)/.test(request.url())
					&& (request.headers().accept || '').includes(NDJSON_ACCEPT)) {
					cleanup();
					resolve({ type: 'request' });
				}
		};
		const onError = error => {
			cleanup();
			resolve({ type: 'pageerror', message: error.message });
		};
		const timer = setTimeout(() => {
			cleanup();
			resolve({ type: 'timeout' });
		}, 10000);
		function cleanup() {
			clearTimeout(timer);
			page.off('request', onRequest);
			page.off('pageerror', onError);
		}
		page.on('request', onRequest);
		page.on('pageerror', onError);
	});
	await page.locator('#exec').click();
	const firstOutcome = await requestOrError;
	expect(firstOutcome.type, `query failed before the execution POST; browser errors: ${monitor.errors.join(' | ')}`
		+ `; observed query POSTs: ${JSON.stringify(monitor.queryPosts)}`)
		.toBe('request');
	await expect.poll(() => monitor.executions.length - previousExecutionCount).toBe(1);
	expect(monitor.executions[previousExecutionCount].accept).toContain(NDJSON_ACCEPT);
	await expect(page.locator('#query-results')).toHaveAttribute('aria-busy', 'false', { timeout: 15000 });
	expect(monitor.errors.slice(previousPageErrorCount), 'the query route must not raise page errors')
		.toEqual([]);
}

async function setEditor(page, index, query) {
	await page.locator('.CodeMirror').nth(index).evaluate((element, value) => {
		element.CodeMirror.setValue(value);
	}, query);
}

async function waitForStableExplanation(page, selector, monitor) {
	try {
		await page.waitForFunction(explanationSelector => {
			const explanation = document.querySelector(explanationSelector);
			const text = explanation && explanation.textContent.trim();
			return text && text !== 'Loading explanation...';
		}, selector, { timeout: 15000 });
	} catch (error) {
		throw new Error(`${error.message}; browser errors: ${monitor.errors.join(' | ')}`);
	}
}

function assertOneStreamingPost(monitor) {
	expect(monitor.executions).toHaveLength(1);
	expect(monitor.executions[0].accept).toContain(NDJSON_ACCEPT);
	const contentType = monitor.executions[0].contentType.toLowerCase();
	const body = monitor.executions[0].body;
	if (contentType.includes('multipart/form-data')) {
		expect(body).not.toMatch(/content-disposition:\s*form-data;\s*name="Accept"/i);
	} else {
		expect(new URLSearchParams(body).get('Accept')).toBeNull();
	}
}

function isNativeDownloadRequest(request) {
	if (request.method() !== 'POST' || !/\/query(?:[?#]|$)/.test(request.url())) {
		return false;
	}
	const parameters = new URLSearchParams(request.postData() || '');
	return parameters.get('action') === 'exec' && !!parameters.get('Accept');
}

function pageErrorsSince(monitor, index) {
	return monitor.errors.slice(index);
}

async function assertBooleanStatus(page, monitor, status) {
	try {
		await expect(page.locator(`#query-results .workbench-status-icon--${status}`)).toBeVisible();
	} catch (error) {
		const state = await page.locator('#query-results').evaluate(root => ({
			busy: root.getAttribute('aria-busy'),
			text: root.innerText,
			resultHtml: root.querySelector('.query-result-layout')
				? root.querySelector('.query-result-layout').outerHTML.slice(0, 3500) : ''
		}));
		await test.info().attach(`boolean-${status}-failure-state.json`, {
			body: Buffer.from(JSON.stringify({ state, errors: monitor.errors,
				queryPosts: monitor.queryPosts, queryResponses: monitor.queryResponses }, null, 2)),
			contentType: 'application/json'
		});
		throw new Error(`${error.message}; boolean result state=${JSON.stringify(state)}`);
	}
}
